    /** Tile tests for map regions shared by two farming regions (the same as RuneLite's isInBounds). */
    enum Bounds
    {
        NONE, PORT_SARIM, FALADOR, CATHERBY_FARM, CATHERBY_FRUIT_TREE, FOSSIL_ISLAND;

        boolean contains(int map, int x, int y, int plane)
        {
            switch (this)
            {
                case PORT_SARIM:
                    return y < 3272;
                case FALADOR:
                    return y >= 3272;
                case CATHERBY_FARM:
                    return map != 11317 || (plane == 0 && x < 2840 && y >= 3440);
                case CATHERBY_FRUIT_TREE:
                    return plane == 1 || !(x < 2840 && y >= 3440);
                case FOSSIL_ISLAND:
                    return plane == 0 && !(x == 3753 && y >= 3868 && y <= 3870) &&
                        !((x == 3728 || x == 3729 || x == 3746 || x == 3747) && y >= 3830 && y <= 3832);
                default:
                    return true;
            }
        }
    }

    static final class Region
    {
        final int id;
        final int[] maps;
        final Bounds bounds;
        final int[] varbits;

        Region(int id, int[] maps, Bounds bounds, int[] varbits)
        {
            this.id = id;
            this.maps = maps;
            this.bounds = bounds;
            this.varbits = varbits;
        }
    }

