    private FarmingRegions() { }

    /** The farming regions whose patches' varbits are valid at this tile. */
    static List<Region> at(int map, int x, int y, int plane)
    {
        List<Region> found = new ArrayList<>();
        for (Region region : ALL)
        {
            for (int candidate : region.maps)
                if (candidate == map && region.bounds.contains(map, x, y, plane))
                {
                    found.add(region);
                    break;
                }
        }
        return found;
    }

    static boolean birdHouseArea(int map)
    {
        for (int candidate : BIRD_HOUSE_MAPS) if (candidate == map) return true;
        return false;
    }
